css:
:root {
  /* Retro Arcade Theme - pixel lights and blacklight cabinet gloss */
  --bg-primary: #0c0b10;
  --bg-alt: #14131d;
  --bg-hover: #1b1a26;
  --text-primary: #fefcf5;
  --text-secondary: #f8d76e;
  --border: #6ef1ff;
  --accent: #ff5f5f;
  --accent-hover: #ffc542;
  --scan: rgba(255, 95, 95, 0.06);
}

[data-theme="light"] {
  --bg-primary: #f7f4ff;
  --bg-alt: #ebe5ff;
  --bg-hover: #d8cfff;
  --text-primary: #1b1626;
  --text-secondary: #4b3c73;
  --border: #6e59ff;
  --accent: #ff5f5f;
  --accent-hover: #ffc542;
  --scan: rgba(110, 89, 255, 0.1);
}

body {
  background: radial-gradient(circle at 50% 0%, rgba(110, 89, 255, 0.24), transparent 45%), var(--bg-primary);
  color: var(--text-primary);
}

.card {
  background: linear-gradient(180deg, var(--bg-alt) 0%, var(--bg-hover) 100%);
  border: 1px solid var(--border);
  box-shadow: 0 12px 32px rgba(0, 0, 0, 0.35), 0 0 0 1px rgba(110, 241, 255, 0.2);
  position: relative;
}

.card::after {
  content: '';
  position: absolute;
  inset: 0;
  background: repeating-linear-gradient(0deg, var(--scan) 0, var(--scan) 2px, transparent 2px, transparent 6px);
  pointer-events: none;
}

.card-title {
  font-family: 'Press Start 2P', 'VT323', monospace;
  letter-spacing: 1.5px;
  color: var(--accent);
  text-shadow: 0 0 10px rgba(255, 95, 95, 0.6);
}
